/**
 * Timezone-aware day boundary helpers for dashboard queries.
 *
 * Uses the Intl API (Node 20 built-in) to find midnight in the studio's
 * local timezone. The returned Date objects are in UTC and safe to pass
 * directly to Supabase `gte` / `lte` filters.
 *
 * No external dependency required — date-fns-tz is NOT a direct dep.
 */

/**
 * Returns the UTC instant that corresponds to 00:00:00.000 in `tz` for the
 * current calendar day (i.e. "start of today" from the studio's perspective).
 */
export function startOfDayInTz(tz: string): Date {
  return dayBoundaryInTz(tz, 'start')
}

/**
 * Returns the UTC instant that corresponds to 23:59:59.999 in `tz` for the
 * current calendar day (i.e. "end of today" from the studio's perspective).
 */
export function endOfDayInTz(tz: string): Date {
  return dayBoundaryInTz(tz, 'end')
}

// ─── Internal ────────────────────────────────────────────────────────────────

function dayBoundaryInTz(tz: string, boundary: 'start' | 'end'): Date {
  // Resolve current wall-clock date in the target timezone
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  })

  // en-CA locale formats as YYYY-MM-DD which is unambiguous
  const localDateStr = formatter.format(new Date()) // e.g. "2026-04-22"

  const [year, month, day] = localDateStr.split('-').map(Number) as [number, number, number]

  // Reconstruct the boundary as a local wall-clock time string, then parse it
  // as if it were UTC. We then offset by the timezone's UTC offset so that
  // the resulting Date is the correct UTC instant for that wall-clock moment.
  if (boundary === 'start') {
    return localMidnightToUtc(year, month, day, 0, 0, 0, 0, tz)
  }
  return localMidnightToUtc(year, month, day, 23, 59, 59, 999, tz)
}

/**
 * Given a wall-clock date + time in `tz`, returns the equivalent UTC Date.
 * We build an ISO string for that wall-clock moment, parse it as UTC, then
 * subtract the offset that the Intl API reports for that instant.
 */
function localMidnightToUtc(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  ms: number,
  tz: string,
): Date {
  // Build a reference UTC Date at the wall-clock instant (temporarily assuming UTC)
  const referenceUtc = new Date(
    Date.UTC(year, month - 1, day, hour, minute, second, ms),
  )

  // Determine what offset the target timezone applies at that approximate moment.
  // We use Intl to extract numeric parts of the same instant rendered in `tz`.
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
    hour12: false,
  }).formatToParts(referenceUtc)

  const get = (type: string): number => {
    const part = parts.find((p) => p.type === type)
    return part ? parseInt(part.value, 10) : 0
  }

  const tzYear = get('year')
  const tzMonth = get('month')
  const tzDay = get('day')
  const tzHour = get('hour') % 24 // Intl returns 24 for midnight in some locales
  const tzMinute = get('minute')
  const tzSecond = get('second')

  // What UTC corresponds to this tz wall-clock?
  // offset = referenceUtc - tzWallClockAsUtc
  const tzWallClockAsUtc = Date.UTC(tzYear, tzMonth - 1, tzDay, tzHour, tzMinute, tzSecond)
  const offsetMs = referenceUtc.getTime() - tzWallClockAsUtc

  // The target wall-clock moment as UTC = naiveUtc + offsetMs
  const naiveUtc = Date.UTC(year, month - 1, day, hour, minute, second, ms)
  return new Date(naiveUtc + offsetMs)
}

/**
 * Server-side data fetcher for the Today's Schedule Timeline widget.
 * Returns all bookings for today grouped by artist, plus studio hours.
 */

import { startOfDayInTz, endOfDayInTz } from './tz-helpers'

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Return types ─────────────────────────────────────────────────────────────

export interface ScheduleBooking {
  id: string
  clientName: string
  scheduledAt: string
  endAt: string
  durationMin: number
  serviceName: string | null
  depositPaid: boolean
  notes: string | null
}

export interface ScheduleArtist {
  id: string
  name: string
  /** hex string or null — from artists.calendar_color */
  color: string | null
  /** True if the artist is a guest (no profile, external) */
  isGuest: boolean
  bookings: ScheduleBooking[]
}

export interface TodayScheduleData {
  artists: ScheduleArtist[]
  /** 24h string "10:00" */
  openTime: string
  /** 24h string "22:00" */
  closeTime: string
  /** True if studio is closed today (operating_hours says so) */
  closedToday: boolean
  hasBookings: boolean
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getTodayScheduleData(
  supabase: SupabaseClient,
  studioId: string,
  /** IANA timezone string from studios.timezone — e.g. "America/New_York" */
  timezone: string = 'UTC',
): Promise<TodayScheduleData> {
  const start = startOfDayInTz(timezone).toISOString()
  const end = endOfDayInTz(timezone).toISOString()

  const bookingsRes = await supabase
    .from('bookings')
    .select(`
      id,
      scheduled_at,
      end_at,
      duration_min,
      deposit_paid,
      notes,
      clients!inner(first_name, last_name),
      artists!inner(id, display_name, calendar_color, profile_id),
      services(name)
    `)
    .eq('studio_id', studioId)
    .gte('scheduled_at', start)
    .lte('scheduled_at', end)
    .in('status', ['pending', 'confirmed', 'in_progress', 'completed'])
    .order('scheduled_at', { ascending: true })

  type BookingRow = {
    id: string
    scheduled_at: string
    end_at: string
    duration_min: number
    deposit_paid: boolean
    notes: string | null
    clients: { first_name: string; last_name: string | null }
    artists: { id: string; display_name: string; calendar_color: string | null; profile_id: string | null }
    services: { name: string } | null
  }

  const bookings = ((bookingsRes.data ?? []) as BookingRow[])

  // Studio hours: default 10:00–22:00. No operating_hours table exists yet;
  // future: pull from booking_page_settings or locations.opening_hours.
  const openTime = '10:00'
  const closeTime = '22:00'
  const closedToday = false

  // Group by artist
  const artistMap = new Map<string, ScheduleArtist>()

  for (const row of bookings) {
    const { id: artistId, display_name, calendar_color, profile_id } = row.artists
    if (!artistMap.has(artistId)) {
      artistMap.set(artistId, {
        id: artistId,
        name: display_name,
        color: calendar_color,
        isGuest: profile_id === null,
        bookings: [],
      })
    }

    const clientName = `${row.clients.first_name} ${row.clients.last_name ?? ''}`.trim()
    artistMap.get(artistId)!.bookings.push({
      id: row.id,
      clientName,
      scheduledAt: row.scheduled_at,
      endAt: row.end_at,
      durationMin: row.duration_min,
      serviceName: row.services?.name ?? null,
      depositPaid: row.deposit_paid,
      notes: row.notes,
    })
  }

  const artists = Array.from(artistMap.values())

  return {
    artists,
    openTime,
    closeTime,
    closedToday,
    hasBookings: bookings.length > 0,
  }
}

