-- W7: Add review_request_sent_at to bookings so Inbox rows auto-resolve
-- after a review request is sent (prevents duplicate SMS/email sends).
--
-- Idempotent: uses DO block + IF NOT EXISTS pattern.

do $$
begin
  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name   = 'bookings'
      and column_name  = 'review_request_sent_at'
  ) then
    alter table public.bookings
      add column review_request_sent_at timestamptz null;
  end if;
end;
$$;

-- Index for the Inbox query: WHERE review_request_sent_at IS NULL
-- Only create if not already present.
do $$
begin
  if not exists (
    select 1
    from pg_indexes
    where schemaname = 'public'
      and tablename  = 'bookings'
      and indexname  = 'bookings_review_request_sent_at_null_idx'
  ) then
    create index bookings_review_request_sent_at_null_idx
      on public.bookings (studio_id)
      where review_request_sent_at is null;
  end if;
end;
$$;

